    _pad0: u32,
    _pad1: u32,
}

struct Input {
    steps: u32,
    dt: f32,
    pos: Vec<[f32; 2]>,
    vel: Vec<[f32; 2]>,
}

fn parse_count(tok: &str, what: &str) -> Result<u64, String> {
    if let Ok(n) = tok.parse::<u64>() {
        return Ok(n);
    }
    match tok.parse::<f64>() {
        Ok(f) if f >= 0.0 && f.fract() == 0.0 && f.is_finite() => Ok(f as u64),
        _ => Err(format!("invalid {what}: {tok:?}")),
    }
}

fn parse_input(text: &str) -> Result<Input, String> {
    let mut toks = text.split_whitespace();
    let mut next = |what: &str| toks.next().ok_or_else(|| format!("missing {what}"));

    let count = parse_count(next("count")?, "count")? as usize;
    let steps = parse_count(next("steps")?, "steps")? as u32;
    let dt_tok = next("dt")?;
    let dt: f64 = dt_tok
        .parse()
        .map_err(|_| format!("invalid dt: {dt_tok:?}"))?;

    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for i in 0..count {
        let mut field = [0f64; 4];
        for f in field.iter_mut() {
            let tok = next("particle field")?;
            *f = tok
                .parse()
                .map_err(|_| format!("invalid field of particle {i}: {tok:?}"))?;
        }
        pos.push([field[0] as f32, field[1] as f32]);
        vel.push([field[2] as f32, field[3] as f32]);
    }
    Ok(Input {
        steps,
        dt: dt as f32,
        pos,
        vel,
    })
}

fn storage_buffer(device: &wgpu::Device, label: &str, data: &[[f32; 2]]) -> wgpu::Buffer {
    device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some(label),
        contents: bytemuck::cast_slice(data),
        usage: wgpu::BufferUsages::STORAGE
            | wgpu::BufferUsages::COPY_SRC
            | wgpu::BufferUsages::COPY_DST,
    })
}

async fn simulate(input: &mut Input) -> Result<(), String> {
    let n = input.pos.len();
    if n == 0 || input.steps == 0 {
        return Ok(());
    }

    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = match instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
    {
        Ok(a) => a,
        Err(_) => instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: wgpu::PowerPreference::None,
                force_fallback_adapter: true,
                compatible_surface: None,
            })
            .await
            .map_err(|e| format!("no GPU adapter available: {e}"))?,
    };
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor {
            label: Some("particles"),
            required_features: wgpu::Features::empty(),
            required_limits: wgpu::Limits::downlevel_defaults().using_resolution(adapter.limits()),
            memory_hints: wgpu::MemoryHints::Performance,
            trace: wgpu::Trace::Off,
        })
        .await
        .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let params = Params {
        count: n as u32,
        dt: input.dt,
        _pad0: 0,
        _pad1: 0,
    };
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let pos_buf = storage_buffer(&device, "pos", &input.pos);
    let vel_buf = storage_buffer(&device, "vel", &input.vel);
    let acc_buf = storage_buffer(&device, "acc", &vec![[0f32; 2]; n]);
    let bytes = (n * std::mem::size_of::<[f32; 2]>()) as u64;
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: bytes * 2,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("gravity"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let make_pipeline = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: None,
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accelerate = make_pipeline("accelerate");
    let integrate = make_pipeline("integrate");

    let bind_group = |pipeline: &wgpu::ComputePipeline| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &pipeline.get_bind_group_layout(0),
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: pos_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: vel_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: acc_buf.as_entire_binding(),
                },
            ],
        })
    };
    let accelerate_bg = bind_group(&accelerate);
    let integrate_bg = bind_group(&integrate);

    let groups = (n as u32).div_ceil(WORKGROUP_SIZE);
    let mut encoder = device.create_command_encoder(&Default::default());
    for _ in 0..input.steps {
        // Separate passes guarantee every acceleration is written before any position moves.
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&accelerate);
            pass.set_bind_group(0, &accelerate_bg, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&integrate);
            pass.set_bind_group(0, &integrate_bg, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &readback, 0, bytes);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &readback, bytes, bytes);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::Wait)
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("readback lost: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;
    {
        let data = slice.get_mapped_range();
        let floats: &[[f32; 2]] = bytemuck::cast_slice(&data);
        input.pos.copy_from_slice(&floats[..n]);
        input.vel.copy_from_slice(&floats[n..]);
    }
    readback.unmap();
    Ok(())
}

fn fmt(v: f64) -> String {
    let s = format!("{v:.6}");
    if s == "-0.000000" {
        "0.000000".to_string()
    } else {
        s
    }
}

fn run() -> Result<(), String> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: gpu-particles <input-file>")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let mut input = parse_input(&text)?;
    pollster::block_on(simulate(&mut input))?;

    let n = input.pos.len().max(1) as f64;
    let (mut sx, mut sy, mut px, mut py, mut ke) = (0f64, 0f64, 0f64, 0f64, 0f64);
    for (p, v) in input.pos.iter().zip(&input.vel) {
        let (vx, vy) = (v[0] as f64, v[1] as f64);
        sx += p[0] as f64;
        sy += p[1] as f64;
        px += vx;
        py += vy;
        ke += (vx * vx + vy * vy) / 2.0;
    }
    let (cx, cy) = (sx / n, sy / n);
    let msd = input
        .pos
        .iter()
        .map(|p| {
            let (dx, dy) = (p[0] as f64 - cx, p[1] as f64 - cy);
            dx * dx + dy * dy
        })
        .sum::<f64>()
        / n;

    println!("CENTER {} {}", fmt(cx), fmt(cy));
    println!("MOMENTUM {} {}", fmt(px), fmt(py));
    println!("KINETIC {}", fmt(ke));
    println!("SPREAD {}", fmt(msd.sqrt()));
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

